// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guessHash, uint256 wobble) public {
        vm.assume(actor != address(0));
        uint256 target = block.number + 1;
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // roll into the window where settle's require passes
        vm.roll(target + (wobble % 10) + 1);

        vm.prank(actor);
        c.settle();

        // general rule: after settle() succeeds, the guess is cleared and any
        // further settle() call must revert.
        vm.roll(target + (wobble % 10) + 2);
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
